#include <bits/stdc++.h>
using namespace std;

using ll = long long;

vector<ll> getPowers(ll base, ll limit) {
    vector<ll> powers;
    ll value = 1;

    while (value <= limit) {
        powers.push_back(value);
        if (base == 1 || (__int128)value * base > limit) break;
        value *= base;
    }

    return powers;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll x, y, l, r;
    cin >> x >> y >> l >> r;

    vector<ll> a = getPowers(x, r);
    vector<ll> b = getPowers(y, r);
    vector<ll> values;

    for (ll i : a) {
        for (ll j : b) {
            __int128 sum = (__int128)i + j;
            if (sum >= l && sum <= r)
                values.push_back((ll)sum);
        }
    }

    values.push_back(l - 1);
    values.push_back(r + 1);

    sort(values.begin(), values.end());
    values.erase(unique(values.begin(), values.end()), values.end());

    ll answer = 0;
    for (size_t i = 1; i < values.size(); ++i)
        answer = max(answer, values[i] - values[i - 1] - 1);

    cout << answer << '\n';
    return 0;
}

