#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using i128 = __int128_t;

vector<ll> getPowers(ll base, ll limit) {
    vector<ll> powers;
    if (limit < 1) return powers;

    ll value = 1;
    while (value <= limit) {
        powers.push_back(value);
        if (base == 1 || (i128)value * base > limit) break;
        value *= base;
    }
    return powers;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll x, y, l, r;
    cin >> x >> y >> l >> r;

    vector<ll> a = getPowers(x, r);
    vector<ll> b = getPowers(y, r);
    vector<ll> sums;

    for (ll i : a) {
        for (ll j : b) {
            i128 sum = (i128)i + j;
            if (sum >= l && sum <= r)
                sums.push_back((ll)sum);
        }
    }

    sort(sums.begin(), sums.end());
    sums.erase(unique(sums.begin(), sums.end()), sums.end());

    ll answer = 0;
    ll previous = l - 1;

    for (ll sum : sums) {
        answer = max(answer, sum - previous - 1);
        previous = sum;
    }

    answer = max(answer, r - previous);
    cout << answer << '\n';

    return 0;
}

